//	value    [valLen]byte (absent for deletes)
//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
const (
	walName = "wal.log"

	recordMagic uint32 = 0x534e4150 // "SNAP"
	opPut       byte   = 1
	opDelete    byte   = 2

	frameHeaderSize = 4 + 1 + 4 + 4
	crcSize         = 4
	maxRecord       = 1 << 30 // sanity bound on key and value lengths
)

type walWriter struct {
	f *os.File
	w *bufio.Writer
}

func openWALWriter(dir string, replaySize int64) (*walWriter, error) {
	f, err := os.OpenFile(dir+string(os.PathSeparator)+walName, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if replaySize >= 0 {
		// Drop any torn tail that replay could not consume.
		if err := f.Truncate(replaySize); err != nil {
			f.Close()
			return nil, err
		}
	}
	if _, err := f.Seek(0, io.SeekEnd); err != nil {
		f.Close()
		return nil, err
	}
	return &walWriter{f: f, w: bufio.NewWriter(f)}, nil
}

// append writes and durably commits one record.
func (l *walWriter) append(op byte, key string, value []byte) error {
	if len(key) > maxRecord || len(value) > maxRecord {
		return fmt.Errorf("snapshot: record too large")
	}
	hdr := make([]byte, frameHeaderSize)
	binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
	hdr[4] = op
	binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
	binary.LittleEndian.PutUint32(hdr[9:13], uint32(len(value)))

	h := crc32.NewIEEE()
	if _, err := h.Write(hdr); err != nil {
		return err
	}
	if _, err := l.w.Write(hdr); err != nil {
		return err
	}
	if _, err := io.WriteString(l.w, key); err != nil {
		return err
	}
	h.Write([]byte(key))
	if op == opPut {
		if _, err := l.w.Write(value); err != nil {
			return err
		}
		h.Write(value)
	}
	var crcb [crcSize]byte
	binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
	if _, err := l.w.Write(crcb[:]); err != nil {
		return err
	}
	if err := l.w.Flush(); err != nil {
		return err
	}
	return l.f.Sync()
}

func (l *walWriter) close() error { return l.f.Close() }

// replayWAL applies every complete, intact record to fn in commit order. It
// returns the number of bytes occupied by the valid prefix; anything after it
// is a torn tail and is discarded on the next open.
func replayWAL(dir string, fn func(op byte, key string, value []byte)) (int64, uint64, error) {
	f, err := os.Open(dir + string(os.PathSeparator) + walName)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return 0, 0, nil
		}
		return 0, 0, err
	}
	defer f.Close()

	r := bufio.NewReader(f)
	var offset int64
	var snapshotCount uint64
	tmp := make([]byte, frameHeaderSize)

	for {
		start := offset
		if _, err := io.ReadFull(r, tmp); err != nil {
			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
				return start, snapshotCount, nil // torn or absent tail: valid prefix ends here
			}
			return 0, 0, err
		}
		offset += frameHeaderSize

		magic := binary.LittleEndian.Uint32(tmp[0:4])
		op := tmp[4]
		keyLen := binary.LittleEndian.Uint32(tmp[5:9])
		valLen := binary.LittleEndian.Uint32(tmp[9:13])
		if magic != recordMagic || (op != opPut && op != opDelete) ||
			keyLen > maxRecord || (op == opDelete && valLen != 0) || valLen > maxRecord {
			// Unrecognized/corrupt frame: treat the rest as an invalid tail.
			return start, snapshotCount, nil
		}

		body := make([]byte, int(keyLen)+int(valLen))
		if _, err := io.ReadFull(r, body); err != nil {
			return start, snapshotCount, nil
		}
		offset += int64(len(body))

		var crcb [crcSize]byte
		if _, err := io.ReadFull(r, crcb[:]); err != nil {
			return start, snapshotCount, nil
		}
		offset += crcSize

		h := crc32.NewIEEE()
		h.Write(tmp)
		h.Write(body)
		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
			return start, snapshotCount, nil
		}

		key := string(body[:keyLen])
		switch op {
		case opPut:
			fn(opPut, key, body[keyLen:])
		case opDelete:
			snapshotCount++
			fn(opDelete, key, nil)
		}
	}
}

