// Package snapshot implements a persistent key-value store whose readers
// operate on immutable point-in-time snapshots. A snapshot never observes a
// write committed after it was acquired, and it keeps serving its fixed view
// even after the store that produced it has been closed.
package snapshot

import (
	"errors"
	"io/fs"
	"os"
	"sync"
	"sync/atomic"
)

// node is one immutable version in a key's history. Versions form a linked
// list from newest to oldest; a snapshot pins the head that was current when
// it was acquired, so old values survive overwrites and deletes until every
// view referencing them goes away.
type node struct {
	value   []byte // nil means the key was deleted at this version
	older   *node
}

// view is an immutable map of keys to their newest version. Store updates
// produce a fresh map; the current view and every snapshot simply point at
// one. Views are never mutated after publication, so reading them needs no
// lock. The maps share version chains with successor views.
type view map[string]*node

// Store is an open key-value store backed by a directory on disk.
type Store struct {
	mu sync.Mutex // serializes writers and guards the fields below

	wal       *walWriter
	current   atomic.Pointer[view] // latest committed view; lock-free for readers
	snapshots uint64               // cumulative number of snapshots handed out

	liveSnapshots sync.WaitGroup // open snapshots derived from this store
	closed        bool
}

// Snapshot is a stable read-only view of a store captured at one instant.
type Snapshot struct {
	v atomic.Pointer[view]
}

// Open opens or creates a persistent store in dir. A path that names a
// regular file rather than a directory returns an error wrapping
// fs.ErrInvalid.
func Open(dir string) (*Store, error) {
	info, err := os.Stat(dir)
	if err == nil {
		if !info.IsDir() {
			return nil, &storeError{err: errInvalidPath, cause: fs.ErrInvalid}
		}
	} else {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return nil, err
		}
	}

	latest := make(view)
	validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte) {
		switch op {
		case opPut:
			v := cloneBytes(value)
			latest[key] = &node{value: v, older: latest[key]}
		case opDelete:
			latest[key] = &node{value: nil, older: latest[key]}
		}
	})
	if err != nil {
		return nil, err
	}

	wal, err := openWALWriter(dir, validSize)
	if err != nil {
		return nil, err
	}

	s := &Store{wal: wal, snapshots: snapshotCount}
	s.current.Store(&latest)
	return s, nil
}

// Put stores value under key. An empty key returns an error wrapping
// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
// key reports a hit.
func (s *Store) Put(key string, value []byte) error {
	if key == "" {
		return errEmptyKey
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errStoreClosed
	}
	if err := s.wal.appendPut(key, value); err != nil {
		return err
	}
	old := *s.current.Load()
	next := make(view, len(old)+1)
	for k, n := range old {
		next[k] = n
	}
	next[key] = &node{value: cloneBytes(value), older: old[key]}
	s.current.Store(&next)
	return nil
}

// Get returns the latest committed value for key. Empty keys, keys never
// written and deleted keys are all misses: ok is false and err is nil.
func (s *Store) Get(key string) ([]byte, bool, error) {
	if key == "" {
		return nil, false, nil
	}
	n := (*s.current.Load())[key]
	if n == nil || n.value == nil {
		return nil, false, nil
	}
	return cloneBytes(n.value), true, nil
}

// Delete removes key. Deleting an empty key returns an error wrapping
// fs.ErrInvalid; deleting a missing or already deleted key is not an error.
func (s *Store) Delete(key string) error {
	if key == "" {
		return errEmptyKey
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errStoreClosed
	}
	cur := *s.current.Load()
	n := cur[key]
	if n != nil && n.value == nil {
		return nil // already deleted in the latest view: idempotent, nothing to commit
	}
	if err := s.wal.appendDelete(key); err != nil {
		return err
	}
	next := make(view, len(cur)+1)
	for k, v := range cur {
		next[k] = v
	}
	next[key] = &node{value: nil, older: n}
	s.current.Store(&next)
	return nil
}

// Snapshot acquires a stable view. The returned Snapshot keeps serving reads
// from that instant regardless of later writes, deletes or Store.Close, until
// the Snapshot itself is closed.
func (s *Store) Snapshot() (*Snapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil, errStoreClosed
	}
	s.snapshots++
	count := s.snapshots
	if err := s.wal.appendMeta(count); err != nil {
		s.snapshots--
		return nil, err
	}
	snap := &Snapshot{}
	snap.v.Store(s.current.Load())
	s.liveSnapshots.Add(1)
	return snap, nil
}

// Get reads key from the snapshot's fixed view. Keys created after the
// snapshot was taken, empty keys and keys deleted before it were taken are
// misses. Reads from a closed snapshot are also plain misses, never errors.
func (s *Snapshot) Get(key string) ([]byte, bool) {
	if key == "" {
		return nil, false
	}
	v := s.v.Load()
	if v == nil {
		return nil, false // closed snapshot
	}
	n := (*v)[key]
	if n == nil || n.value == nil {
		return nil, false
	}
	return cloneBytes(n.value), true
}

// Close releases the snapshot's fixed view. Closing more than once is a
// no-op returning nil.
func (s *Snapshot) Close() error {
	if s.v.Swap(nil) == nil {
		return nil
	}
	// The snapshot may be store-backed or, in principle, standalone; only
	// store-backed snapshots are tracked by their parent's WaitGroup.
	if onClose := snapshotOnClose(s); onClose != nil {
		onClose()
	}
	return nil
}

// Close flushes and closes the store. Already-committed data stays readable
// after reopening the directory. Snapshots still open keep serving their
// fixed views; closing an already closed store is a no-op returning nil.
func (s *Store) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	wal := s.wal
	s.wal = nil
	s.mu.Unlock()

	err := wal.close()
	s.liveSnapshots.Wait()
	return err
}

func cloneBytes(b []byte) []byte {
	if b == nil {
		return nil
	}
	c := make([]byte, len(b))
	copy(c, b)
	return c
}

