		s.mu.Unlock()
		return nil
	}
	wal := s.wal
	s.wal = nil
	s.mu.Unlock()

	return wal.close()
}

func lookup(v view, key string) ([]byte, bool) {
	n := v[key]
	if n == nil || !n.present {
		return nil, false
	}
	return cloneBytes(n.value), true
}

func cloneBytes(b []byte) []byte {
	if b == nil {
		return nil
	}
	c := make([]byte, len(b))
	copy(c, b)
	return c
}

package snapshot

// Stats describes the current state of a store.
type Stats struct {
	// Keys is the number of live keys (present values) in the latest view.
	Keys int
	// Snapshots is the cumulative number of snapshots successfully handed
	// out by this store across all openings of the same directory.
	Snapshots uint64
	// AvgBytes is the mean length of live values, rounded to two decimal
	// places. It is 0 when there are no live keys.
	AvgBytes float64
}

// Stats returns statistics over the latest committed view. It does not count
// as taking a snapshot.
func (s *Store) Stats() Stats {
	v := *s.current.Load()
	var keys int
	var totalBytes int
	for _, n := range v {
		if n.present {
			keys++
			totalBytes += len(n.value)
		}
	}
	st := Stats{Keys: keys, Snapshots: s.snapshots}
	if keys > 0 {
		st.AvgBytes = roundHundredth(float64(totalBytes) / float64(keys))
	}
	return st
}

// roundHundredth rounds x to two decimal places using round-half-away-from-
// zero. Stats inputs are non-negative.
func roundHundredth(x float64) float64 {
	return float64(int64(x*100.0+0.5)) / 100.0
}

