// Command snapshotctl inspects snapshot-kv stores.
//
// Usage:
//
//	snapshotctl --dir <path> stats
//
// stats prints one compact JSON line, terminated by a newline:
//
//	{"keys":3,"snapshots":2,"avgBytes":4.67}
package main

import (
	"fmt"
	"os"

	"github.com/Hulalalalalalalalalalala/snapshot-kv"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	dir, cmd, ok := parseArgs(args)
	if !ok || cmd != "stats" {
		return 1
	}

	store, err := snapshot.Open(dir)
	if err != nil {
		// Directory cannot be opened: exit 1 and print nothing.
		return 1
	}
	defer store.Close()

	st := store.Stats()
	// Fixed key order keys, snapshots, avgBytes; no spaces. %.2f always
	// emits exactly two decimals and never "-0" for non-negative inputs.
	fmt.Printf("{\"keys\":%d,\"snapshots\":%d,\"avgBytes\":%.2f}\n",
		st.Keys, st.Snapshots, st.AvgBytes)
	return 0
}

// parseArgs accepts "--dir <path> stats" (or "--dir=<path>").
func parseArgs(args []string) (dir, cmd string, ok bool) {
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--dir" || a == "-dir":
			if i+1 >= len(args) {
				return "", "", false
			}
			dir = args[i+1]
			i++
		case len(a) > 6 && a[:6] == "--dir=":
			dir = a[6:]
		default:
			if a == "stats" && cmd == "" {
				cmd = a
			} else {
				return "", "", false
			}
		}
	}
	if dir == "" || cmd == "" {
		return "", "", false
	}
	return dir, cmd, true
}

