			t.Fatal(err)
		}
	}

	// Total 10 bytes over 3 keys: 3.33.
	putLen("a", 4)
	putLen("b", 4)
	putLen("c", 2) // empty-value case covered separately
	if st := s.Stats(); st.Keys != 3 || st.AvgBytes != 3.33 {
		t.Fatalf("stats: %+v", st)
	}

	// Half-up tie at the third decimal: 1/8 = 0.125 -> 0.13.
	if err := s.Delete("b"); err != nil {
