func TestConcurrentIsolation(t *testing.T) {
	s := openStore(t, tempDir(t))

	const writers = 4
	const iterations = 200
	var wg sync.WaitGroup
	stop := make(chan struct{})
	var failures int64
	var failMu sync.Mutex
	fail := func(format string, args ...any) {
		t.Errorf(format, args...)
		failMu.Lock()
		failures++
		failMu.Unlock()
	}

	// Writers overwrite one key per goroutine with self-describing values.
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			key := fmt.Sprintf("k%d", w)
			for i := 0; i < iterations; i++ {
				v := bytes.Repeat([]byte{byte('a' + w)}, i+1)
				if err := s.Put(key, v); err != nil {
					fail("put: %v", err)
					return
				}
			}
		}(w)
	}

	// Readers repeatedly snapshot and verify:
	//  - every value is a whole, un-torn prefix of its expected alphabet;
	//  - re-reading the same snapshot returns identical bytes.
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			snap, err := s.Snapshot()
			if err != nil {
				fail("snapshot: %v", err)
				return
			}
			for w := 0; w < writers; w++ {
				key := fmt.Sprintf("k%d", w)
				v, ok := snap.Get(key)
				if !ok {
					continue // key may not have been written yet
				}
				if !allByte(v, byte('a'+w)) {
					fail("torn/aliased value for %s: %q", key, v)
				}
				v2, ok := snap.Get(key)
				if !ok || !bytes.Equal(v, v2) {
					fail("snapshot view changed between reads")
				}
			}
			snap.Close()
		}
	}()

	wgAddWg := wg
	_ = wgAddWg
	writersDone := make(chan struct{})
	go func() {
		// Wait only for writers by tracking separately below.
		close(writersDone)
	}()

	// Simpler: just wait for all via the same wg by stopping reader first is
	// awkward; track writer completion explicitly instead.
	wg.Wait() // reader goroutine is stopped via stop() in dedicated below
	close(stop)
}

func allByte(b []byte, c byte) bool {
	for _, x := range b {
		if x != c {
			return false
		}
	}
	return true
}

